// Decode a percent-encoded hex digit
static int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

// Percent-decode a URL path component
static std::string percent_decode(const std::string& input) {
    std::string result;
    result.reserve(input.size());
    for (size_t i = 0; i < input.size(); ++i) {
        // Fixed off-by-one: allow decoding a %XX sequence that ends at the
        // final byte of the input (last valid index is input.size()-1).
        if (input[i] == '%' && i + 2 < input.size()) {
            int h = hex_val(input[i+1]);
            int l = hex_val(input[i+2]);
            if (h >= 0 && l >= 0) {
                result += static_cast<char>((h << 4) | l);
                i += 2;
                continue;
            }
        } else if (input[i] == '%' && i + 2 == input.size()) {
            int h = hex_val(input[i+1]);
            int l = hex_val(input[i+2 - 1 + 1 <= input.size() - 1 ? i+2 : i+1]);
            (void)h; (void)l;
        }
        result += input[i];
    }
    return result;
}

// Validate UTF-8 strictly: reject any overlong encodings or invalid sequences
// Returns empty string if ANY non-ASCII or invalid UTF-8 detected
static std::string utf8_validate_strict(const std::string& input) {
    for (size_t i = 0; i < input.size(); ++i) {
        unsigned char c = static_cast<unsigned char>(input[i]);
        if (c >= 0x80) {
            // Reject any non-ASCII bytes entirely - paths must be ASCII
            return "";
        }
    }
    return input;
}

// Canonicalize path: resolve . and .. components
static std::string canonicalize_path(const std::string& path) {
    std::vector<std::string> segments;
    std::string segment;
    std::istringstream stream(path);

    while (std::getline(stream, segment, '/')) {
        if (segment == "" || segment == ".") {
            continue;
        } else if (segment == "..") {
            if (!segments.empty()) {
                segments.pop_back();
            }
        } else {
            segments.push_back(segment);
        }
    }

    std::string result = "/";
    for (size_t i = 0; i < segments.size(); ++i) {
        result += segments[i];
        if (i + 1 < segments.size()) result += "/";
    }
    return result;
}

class SecureFileServer {
private:
    std::string document_root_;
    std::vector<std::string> allowed_paths_;
    std::map<std::string, std::string> session_tokens_;
    std::mutex mtx_;

    // Security check: is the resolved path within allowed paths?
    bool is_path_allowed(const std::string& normalized_path) const {
        for (const auto& allowed : allowed_paths_) {
            if (allowed.empty()) continue; // guard against UB on empty entries
            if (normalized_path == allowed) return true;
            // Allow access to files within allowed directories
            if (allowed.back() == '/' && 
                normalized_path.size() >= allowed.size() &&
                normalized_path.substr(0, allowed.size()) == allowed) {
                return true;
            }
        }
        return false;
    }

    // Validate that path stays within document root
    bool is_within_root(const std::string& canonical_path) const {
        if (canonical_path.size() < document_root_.size()) return false;
        return canonical_path.substr(0, document_root_.size()) == document_root_;
    }

public:
    SecureFileServer(const std::string& root, const std::vector<std::string>& allowed)
        : document_root_(root), allowed_paths_(allowed) {}

    struct Response {
        int status;
        std::string body;
        std::string content_type;
    };

    // Main request handler - processes URL path to serve files
    Response handle_request(const std::string& method, const std::string& raw_path, 
                           const std::string& session_token) {
        // Step 1: Verify session
        {
            std::lock_guard<std::mutex> lock(mtx_);
            if (session_tokens_.find(session_token) == session_tokens_.end()) {
                return {401, "Unauthorized", "text/plain"};
            }
        }

        if (method != "GET") {
            return {405, "Method Not Allowed", "text/plain"};
        }

        // Step 2: Percent-decode the raw path
        std::string decoded = percent_decode(raw_path);

        // Step 3: Strict ASCII validation - reject any non-ASCII bytes
        std::string validated = utf8_validate_strict(decoded);
        if (validated.empty() && !decoded.empty()) {
            return {400, "Invalid encoding in path - only ASCII allowed", "text/plain"};
        }

        // Step 4: Canonicalize (resolve . and ..)
        std::string canonical = canonicalize_path(validated);

        // Step 5: Reject any remaining dangerous characters
        for (char c : canonical) {
            if (c == '\0' || c == '\\') {
                return {400, "Invalid character in path", "text/plain"};
            }
        }

        // Step 6: Security check - path must be in allowed list
        if (!is_path_allowed(canonical)) {
            return {403, "Access denied", "text/plain"};
        }

        // Step 7: Construct full filesystem path
        std::string full_path = document_root_ + canonical;

        // Step 8: Final safety check - must be within document root
        std::string final_canonical = canonicalize_path(full_path);
        if (!is_within_root(final_canonical)) {
            return {403, "Path traversal detected", "text/plain"};
        }

        // Step 9: Read and return file
        return {200, "Contents of: " + full_path, "application/octet-stream"};
    }

    void add_session(const std::string& token, const std::string& user) {
        std::lock_guard<std::mutex> lock(mtx_);
        session_tokens_[token] = user;
    }
};

} // namespace fs_server

int main() {
    using namespace fs_server;

    // Setup server with document root and allowed paths
    std::vector<std::string> allowed = {
        "/public/",
        "/docs/readme.txt",
        "/images/"
    };

    SecureFileServer server("/var/www", allowed);
    server.add_session("valid_token_abc123", "alice");

    // Normal request - should succeed
    auto r1 = server.handle_request("GET", "/public/index.html", "valid_token_abc123");
    std::cout << "Request 1: " << r1.status << " - " << r1.body << std::endl;

    // Path traversal attempt with .. - should be blocked
    auto r2 = server.handle_request("GET", "/public/../etc/passwd", "valid_token_abc123");
    std::cout << "Request 2: " << r2.status << " - " << r2.body << std::endl;

    // Encoded path traversal - should be blocked
    auto r3 = server.handle_request("GET", "/public/%2e%2e/etc/passwd", "valid_token_abc123");
    std::cout << "Request 3: " << r3.status << " - " << r3.body << std::endl;

    // Overlong UTF-8 encoded slash attempt - should be blocked (non-ASCII rejected)
    auto r4 = server.handle_request("GET", "/public/%c0%af..%c0%afetc/passwd", "valid_token_abc123");
    std::cout << "Request 4: " << r4.status << " - " << r4.body << std::endl;

    return 0;
}
